    async def mouse_click(
        self,
        session_id: str,
        *,
        x: float | NotGiven = not_given,
        y: float | NotGiven = not_given,
        button: Literal["left", "middle", "right"] | NotGiven = not_given,
        selector: str | NotGiven = not_given,
        timeout_: float | NotGiven = not_given,
        index: float | NotGiven = not_given,
        extra_headers: Headers | None = None,
        extra_query: Query | None = None,
        extra_body: Body | None = None,
        timeout: float | httpx.Timeout | None | NotGiven = not_given,
    ) -> models.SessionsMouseClickResponse:
        """
        Mouse Click

        Performs a mouse click at the specified coordinates

        Args:
          session_id: The ID of the browser session
          x: X coordinate
          y: Y coordinate
          button: Mouse button to use
          selector: A valid CSS selector for the requested element
          timeout_: If a selector was passed, timeout in ms for waiting for the DOM element to be
          selected. Defaults to 5000 (5 seconds).
          index: If a selector was passed and multiple elements match the selector, the index of
          the element in the list (0-based). Defaults to 0.
        """
        if not session_id:
            raise ValueError(f"Expected a non-empty value for `session_id` but received {session_id!r}")
        return await self._post(
            path_template("/v1/sessions/{sessionId}/mouse/click", sessionId=session_id),
            body=strip_not_given(
                {"x": x, "y": y, "button": button, "selector": selector, "timeout": timeout_, "index": index}
            ),
            options=make_request_options(
                extra_headers=extra_headers, extra_query=extra_query, extra_body=extra_body, timeout=timeout
            ),
            cast_to=models.SessionsMouseClickResponse,
        )

